	<description>Demo project for Spring Boot REST</description>
	<properties>
		<java.version>17</java.version>
	</properties>
	<dependencies>
		<dependency>
			<groupId>org.springframework.boot</groupId>
			<artifactId>spring-boot-starter-web</artifactId>
		</dependency>

		<dependency>
			<groupId>org.springframework.boot</groupId>
			<artifactId>spring-boot-starter-test</artifactId>
			<scope>test</scope>
		</dependency>
	</dependencies>

	<build>
		<plugins>
			<plugin>
				<groupId>org.springframework.boot</groupId>
				<artifactId>spring-boot-maven-plugin</artifactId>
			</plugin>
		</plugins>
	</build>

</project>"},{"order":7,"type":"heading","text":"Creating a REST Controller"},{"order":8,"type":"paragraph","text":"A REST controller is a class annotated with `@RestController`. This annotation combines `@Controller` and `@ResponseBody`.  `@Controller` indicates that the class handles incoming web requests, and `@ResponseBody` indicates that the return value of the methods should be bound to the body of the web response."},{"order":9,"type":"subheading","text":"Example Controller"},{"order":10,"type":"code","text":"package com.example.restexample.controller;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class HelloController {

    @GetMapping("/hello")
    public String hello() {
        return "Hello, World!";
    }

    @GetMapping("/hello/{name}")
    public String helloName(@PathVariable String name) {
        return "Hello, " + name + "!";
    }

    @GetMapping("/greet")
    public String greet(@RequestParam(value = "name", defaultValue = "World") String name) {
        return "Greetings, " + name + "!";
    }
}
"},{"order":11,"type":"paragraph","text":"In this example:"},{"order":12,"type":"bullet_point","text":"`@RestController` marks the class as a REST controller."},{"order":13,"type":"bullet_point","text":"`@GetMapping("/hello")` maps HTTP GET requests for the `/hello` endpoint to the `hello()` method.  This method returns a simple "Hello, World!" string."},{"order":14,"type":"bullet_point","text":"`@GetMapping("/hello/{name}")` maps GET requests for `/hello/{name}`.  `@PathVariable String name` extracts the value from the URL path and passes it as the `name` argument to the `helloName()` method.  For example, a request to `/hello/John` would return "Hello, John!"."},{"order":15,"type":"bullet_point","text":"`@GetMapping("/greet")` maps GET requests for `/greet`. `@RequestParam(value = "name", defaultValue = "World") String name` extracts the value of the `name` query parameter. If the `name` parameter is not provided, it defaults to "World". For example, a request to `/greet?name=Jane` would return "Greetings, Jane!". A request to `/greet` would return "Greetings, World!"."},{"order":16,"type":"heading","text":"HTTP Request Methods"},{"order":17,"type":"paragraph","text":"Spring provides annotations for mapping different HTTP request methods:"},{"order":18,"type":"bullet_point","text":"`@GetMapping`: For handling GET requests (retrieving data)."},{"order":19,"type":"bullet_point","text":"`@PostMapping`: For handling POST requests (creating data)."},{"order":20,"type":"bullet_point","text":"`@PutMapping`: For handling PUT requests (updating existing data)."},{"order":21,"type":"bullet_point","text":"`@DeleteMapping`: For handling DELETE requests (deleting data)."},{"order":22,"type":"bullet_point","text":"`@PatchMapping`: For handling PATCH requests (partially updating existing data)."},{"order":23,"type":"heading","text":"Handling POST Requests and Request Bodies"},{"order":24,"type":"paragraph","text":"To handle POST requests, use the `@PostMapping` annotation. To access the data sent in the request body, use the `@RequestBody` annotation.  Spring automatically converts the JSON or XML request body to a Java object."},{"order":25,"type":"subheading","text":"Example with @RequestBody"},{"order":26,"type":"code","text":"package com.example.restexample.controller;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class UserController {

    @PostMapping("/users")
    public User createUser(@RequestBody User user) {
        // Process the user data (e.g., save to a database)
        System.out.println("Received user: " + user);
        return user; // Return the created user (usually with an ID)
    }
}

class User {
    private String name;
    private String email;

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    @Override
    public String toString() {
        return "User{" +
                "name='" + name + '\'' +
                ", email='" + email + '\'' +
                '}';
    }
}
"},{"order":27,"type":"paragraph","text":"In this example, the `createUser()` method handles POST requests to `/users`.  The `@RequestBody User user` annotation tells Spring to convert the JSON request body into a `User` object. The method then processes the user data and returns the created user.  The returned `User` object will be automatically converted to JSON in the response."},{"order":28,"type":"heading","text":"Returning Responses"},{"order":29,"type":"paragraph","text":"REST controllers can return various types of responses:"},{"order":30,"type":"bullet_point","text":"Simple values (String, Integer, etc.): These are converted to a string representation in the response body."},{"order":31,"type":"bullet_point","text":"Objects: These are automatically serialized to JSON (or XML if configured) using a message converter (like Jackson for JSON)."},{"order":32,"type":"bullet_point","text":"`ResponseEntity`: This allows you to control the response status code, headers, and body. It provides more flexibility in crafting the response."},{"order":33,"type":"subheading","text":"Using ResponseEntity"},{"order":34,"type":"code","text":"package com.example.restexample.controller;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ProductController {

    @GetMapping("/products/{id}")
    public ResponseEntity<Product> getProduct(@PathVariable int id) {
        Product product = findProductById(id);

        if (product != null) {
            return new ResponseEntity<>(product, HttpStatus.OK);
        } else {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
    }

    private Product findProductById(int id) {
        // Simulate retrieving a product from a database
        if (id == 1) {
            return new Product("Laptop", 1200.00);
        } else {
            return null;
        }
    }
}

class Product {
    private String name;
    private double price;

    public Product(String name, double price) {
        this.name = name;
        this.price = price;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }
}
"},{"order":35,"type":"paragraph","text":"In this example, the `getProduct()` method retrieves a product based on its ID. If the product is found, it returns a `ResponseEntity` with the product and an HTTP status code of 200 (OK). If the product is not found, it returns a `ResponseEntity` with an HTTP status code of 404 (NOT_FOUND)."},{"order":36,"type":"heading","text":"Exception Handling"},{"order":37,"type":"paragraph","text":"Proper exception handling is crucial for robust REST APIs. Spring provides several ways to handle exceptions globally or within specific controllers."},{"order":38,"type":"subheading","text":"@ExceptionHandler"},{"order":39,"type":"paragraph","text":"The `@ExceptionHandler` annotation allows you to handle exceptions within a specific controller.  It's a method-level annotation that specifies which exception type the method should handle."},{"order":40,"type":"subheading","text":"@ControllerAdvice"},{"order":41,"type":"paragraph","text":"The `@ControllerAdvice` annotation allows you to create global exception handlers that apply to all controllers. This is useful for handling common exceptions consistently across your application."},{"order":42,"type":"subheading","text":"Example Exception Handling using @ControllerAdvice"},{"order":43,"type":"code","text":"package com.example.restexample.controller;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;

@ControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ResourceNotFoundException.class)
    public ResponseEntity<String> handleResourceNotFound(ResourceNotFoundException ex) {
        return new ResponseEntity<>(ex.getMessage(), HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<String> handleGenericException(Exception ex) {
        return new ResponseEntity<>("An unexpected error occurred: " + ex.getMessage(), HttpStatus.INTERNAL_SERVER_ERROR);
    }
}

class ResourceNotFoundException extends RuntimeException {
    public ResourceNotFoundException(String message) {
        super(message);
    }
}
"},{"order":44,"type":"paragraph","text":"In this example, `GlobalExceptionHandler` is annotated with `@ControllerAdvice`, making it a global exception handler. The `handleResourceNotFound()` method handles `ResourceNotFoundException` exceptions, returning a 404 NOT_FOUND status with the exception message. The `handleGenericException` method handles all other exceptions, returning a 500 INTERNAL_SERVER_ERROR status with a generic error message.  Any controller that throws a `ResourceNotFoundException` will now be handled by this global handler."},{"order":45,"type":"paragraph","text":"To use the exception handler, you would throw the `ResourceNotFoundException` from within your controller."},{"order":46,"type":"code","text":"package com.example.restexample.controller;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ExampleController {

    @GetMapping("/example/{id}")
    public ResponseEntity<String> getExample(@PathVariable int id) {
        if (id == 0) {
            throw new ResourceNotFoundException("Example with ID 0 not found");
        }
        return new ResponseEntity<>("Example with ID " + id, HttpStatus.OK);
    }
}
"},{"order":47,"type":"heading","text":"Validation"},{"order":48,"type":"paragraph","text":"Validating request data is essential for ensuring data integrity. Spring Boot integrates seamlessly with the Bean Validation API (JSR-380) to provide a powerful validation mechanism."},{"order":49,"type":"subheading","text":"Enabling Validation"},{"order":50,"type":"paragraph","text":"Add the `spring-boot-starter-validation` dependency to your `pom.xml`."},{"order":51,"type":"code","text":"<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-validation</artifactId>
</dependency>"},{"order":52,"type":"paragraph","text":"Annotate your request body parameter with `@Valid` to enable validation. Use validation annotations from the `javax.validation.constraints` package to define validation rules."},{"order":53,"type":"subheading","text":"Example with Validation"},{"order":54,"type":"code","text":"package com.example.restexample.controller;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotEmpty;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.*;

@RestController
public class ValidationController {

    @PostMapping("/validate")
    public ResponseEntity<String> validateUser(@Valid @RequestBody ValidUser user) {
        return new ResponseEntity<>("User is valid!", HttpStatus.OK);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<String> handleValidationExceptions(MethodArgumentNotValidException ex) {
        return new ResponseEntity<>("Validation failed: " + ex.getBindingResult().getAllErrors().get(0).getDefaultMessage(), HttpStatus.BAD_REQUEST);
    }
}

class ValidUser {
    @NotEmpty(message = "Name cannot be empty")
    private String name;

    @Email(message = "Email should be valid")
    private String email;

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }
}
"},{"order":55,"type":"paragraph","text":"In this example, the `ValidUser` class has validation annotations for the `name` and `email` fields. `@NotEmpty` ensures that the `name` field is not empty, and `@Email` ensures that the `email` field is a valid email address. The `@Valid` annotation on the `user` parameter in the `validateUser()` method triggers the validation process. If validation fails, a `MethodArgumentNotValidException` is thrown, which is handled by the `handleValidationExceptions()` method. This method returns a 400 BAD_REQUEST status with a message indicating the validation failure."},{"order":56,"type":"heading","text":"Conclusion"},{"order":57,"type":"paragraph","text":"This tutorial covered the basics of creating REST controllers in Spring Boot, including handling different HTTP request methods, processing request bodies, returning responses, handling exceptions, and validating request data. By following these guidelines, you can build robust and well-structured RESTful APIs with Spring Boot."}]
